                    self.tcx
                        .sess
                        .struct_span_err(provided_arg.span, "this argument must be a function item")
                        .note(format!("expected a function item, found {checked_ty}"))
                        .help(
                            "consult the documentation on `const_eval_select` for more information",
                        )
                        .emit();
                }
            }

